-- PT119-S4-Q9. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT119-S4-Q9$batch10$ AND q.stimulus=$batch10$Journalist: A free marketplace of ideas ensures that all ideas get a fair hearing. Even ideas tainted with prejudice and malice can prompt beneficial outcomes. In most countries, however, the government is responsible for over half the information released to the public through all media. For this reason, the power of governments over information needs to be curtailed. Everyone grants that governments should not suppress free expression, yet governments continue to construct near monopolies on the publication and dissemination of enormous amounts of information.$batch10$ AND q.prompt=$batch10$Which one of the following most accurately expresses the conclusion of the journalist's argument?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT119-S4-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT119-S4-Q9$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S4-Q9'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT119-S4-Q9$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Evidence$batch10$, $batch10$A free marketplace of ideas gives all ideas a fair hearing, and even prejudiced ideas can do good. In most countries, the government releases over half the information the public gets through the media.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$Governments' power over information needs to be curtailed.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Everyone agrees governments shouldn't suppress free expression, yet they keep building near monopolies on information.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"For this reason" flags the conclusion in the fourth sentence. The sentences before it and the last sentence all support it.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Governments' control over information should be reduced.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT119-S4-Q9$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The journalist doesn't say the free marketplace is in jeopardy. That's a background worry, not the claim argued for.$batch10$), ($batch10$B$batch10$, $batch10$The value of a free marketplace is part of the support.$batch10$), ($batch10$C$batch10$, $batch10$"Curtailed" means reduced. This restates the sentence that "For this reason" introduces.$batch10$), ($batch10$D$batch10$, $batch10$This restates the second sentence, which supports the value of a free marketplace.$batch10$), ($batch10$E$batch10$, $batch10$This is the closing sentence, which adds support for curtailing government power.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT119-S4-Q9$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
